  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Determine whether this booking satisfies all eligibility rules: non-null inputs, trip existence, seat availability, non-overlapping customer bookings on the same day, and booking time strictly more than two hours before departure.
   * Algorithm:
   * 1. If bookingDate, customer, or trip is null, return false.
   * 2. If booking.numberOfSeats <= 0, return false.
   * 3. Check that trip.numberOfSeats minus trip.getBookedSeats() is at least booking.numberOfSeats.
   * 4. For each existing booking in customer.bookings:
   *    a. If the existing booking is on the same day as bookingDate.
   *    b. If existing booking.trip overlaps with this.trip (same-day time overlap), return false.
   * 5. Parse trip.departureTime and bookingDate time context.
   * 6. If bookingDate is not strictly earlier than trip departure time by more than 2 hours, return false.
   * 7. Otherwise return true.
   * Related Features:
   * - bookingDate
   * - numberOfSeats
   * - customer
   * - trip
   * - customer.bookings
   * - trip.numberOfSeats
   * - trip.departureTime
   * - Trip.getBookedSeats()
   * Related Classes: Booking, Customer, Trip, User
   * Input:
   * - None explicitly; the operation uses the current Booking instance state.
   * - bookingDate: EDate, must represent the booking timestamp/date.
   * - customer: Customer, must reference the booking owner.
   * - trip: Trip, must reference the trip to be booked.
   * - numberOfSeats: int, requested seats; expected > 0.
   * Output:
   * - boolean: true if the booking is eligible; otherwise false.
   * Pre-condition:
   * - The Booking object exists.
   * - bookingDate, customer, and trip may be absent, but if any is null the method must return false.
   * - Trip departure time and booking date/time must be interpretable for a 2-hour lead-time comparison.
   * Post-condition:
   * - No persistent state is modified.
   * - If the result is true, the booking satisfies all eligibility rules required by ORS.
   * <!-- end-model-doc -->
   * @model kind="operation"
   *        annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean isBookingEligible()
  {
    if (bookingDate == null || customer == null || trip == null)
    {
      return false;
    }
    if (numberOfSeats <= 0)
    {
      return false;
    }
    if (trip.getNumberOfSeats() - trip.getBookedSeats() < numberOfSeats)
    {
      return false;
    }
    if (customer.getBookings() != null)
    {
      for (Booking existingBooking : customer.getBookings())
      {
        if (existingBooking != null && existingBooking != this)
        {
          if (existingBooking.getBookingDate() != null && isSameDay(existingBooking.getBookingDate(), bookingDate))
          {
            if (existingBooking.getTrip() != null && overlapsWith(existingBooking.getTrip()))
            {
              return false;
            }
          }
        }
      }
    }

    Date departure = null;
    if (trip.getDepartureTime() != null)
    {
      try
      {
        departure = java.sql.Timestamp.valueOf(trip.getDepartureTime());
      }
      catch (IllegalArgumentException e)
      {
        return false;
      }
    }
    if (departure == null)
    {
      return false;
    }
    long diff = departure.getTime() - bookingDate.getTime();
    if (diff <= 2L * 60L * 60L * 1000L)
    {
      return false;
    }
    return true;
  }

